import org.gradle.api.artifacts.VersionCatalogsExtension
import org.gradle.api.plugins.JavaPluginExtension
import org.gradle.api.tasks.compile.JavaCompile
import org.gradle.api.publish.PublishingExtension
import org.gradle.api.publish.maven.MavenPublication
import org.gradle.api.tasks.testing.logging.TestExceptionFormat

plugins {
    base
}

allprojects {
    group = "io.github.diodeme.ji"
    version = "0.1.0-SNAPSHOT"
}

val rootLibraries = extensions.getByType<VersionCatalogsExtension>().named("libs")

subprojects {
    apply(plugin = "java-library")
    apply(plugin = "maven-publish")

    extensions.configure<JavaPluginExtension> {
        toolchain {
            languageVersion.set(JavaLanguageVersion.of(21))
        }
        withSourcesJar()
        withJavadocJar()
    }

    tasks.withType<JavaCompile>().configureEach {
        options.encoding = "UTF-8"
        options.release.set(21)
        options.compilerArgs.addAll(listOf("-Xlint:all", "-Werror"))
        mustRunAfter(":verifyGenerated")
    }

    tasks.withType<Test>().configureEach {
        useJUnitPlatform()
        testLogging {
            exceptionFormat = TestExceptionFormat.FULL
        }
    }

    extensions.configure<PublishingExtension> {
        repositories.maven {
            name = "stage1"
            url = rootProject.layout.buildDirectory.dir("stage1-repository").get().asFile.toURI()
        }
        publications.create<MavenPublication>("java") {
            from(components.getByName("java"))
        }
    }

    dependencyLocking {
        lockAllConfigurations()
    }

    dependencies {
        "testImplementation"(platform(rootLibraries.findLibrary("junit-bom").get()))
        "testImplementation"(rootLibraries.findLibrary("junit-jupiter").get())
        "testRuntimeOnly"(rootLibraries.findLibrary("junit-platform-launcher").get())
    }
}

tasks.register<Exec>("generateContracts") {
    description = "Generates checked-in contracts from canonical sources."
    commandLine("node", "scripts/generate-contracts.mjs")
}

tasks.register<Exec>("verifyGenerated") {
    description = "Regenerates contracts and verifies a zero diff."
    commandLine("node", "scripts/verify-generated.mjs")
}

tasks.register<Exec>("verifyFixtures") {
    description = "Runs the TypeScript oracle and Java fixture runner comparison."
    dependsOn(
        ":ji-test-kit:runFixtures",
        ":ji-test-kit:test",
    )
    val javaOutput = layout.buildDirectory.file("fixture/java-projections.json")
    inputs.file("contracts/fixtures/manifest.json")
    inputs.dir("contracts/fixtures/pi-6c87d9a")
    inputs.file(javaOutput)
    commandLine("node", "scripts/verify-fixtures.mjs", "--java-output", javaOutput.get().asFile.absolutePath)
}

tasks.register("stage0Check") {
    description = "Runs all Stage 0 offline verification gates."
    dependsOn("verifyGenerated", "verifyFixtures")
    dependsOn(subprojects.map { "${it.path}:check" })
}

tasks.register<Exec>("verifyApiBaseline") {
    description = "Verifies the Stage 1 public API inventory baseline."
    commandLine("node", "scripts/verify-api-baseline.mjs")
}

tasks.register("stage1Check") {
    description = "Runs Stage 1 Java and contract verification without real providers."
    dependsOn("stage0Check", "verifyApiBaseline")
    dependsOn(subprojects.map { "${it.path}:check" })
}

tasks.register("stage2FoundationCheck") {
    description = "Runs the Stage 2 canonical Session/Store/queue foundation and Stage 0-1 regression gates."
    dependsOn("stage1Check")
    dependsOn(
        ":ji-session-memory:test",
        ":ji-session-jsonl:test",
        ":ji-session-sqlite:test",
        ":ji-host-core:test",
    )
}

tasks.register<Exec>("verifyModuleBoundaries") {
    description = "Verifies dependency direction and module ownership boundaries."
    commandLine("node", "scripts/verify-module-boundaries.mjs")
}

tasks.register<Exec>("verifyPublicNaming") {
    description = "Verifies public Java naming and package contracts."
    commandLine("node", "scripts/verify-naming.mjs")
}

tasks.register<Exec>("stage2NativeWorkspaceSmoke") {
    description = "Runs the Stage 2 workspace/path smoke on the current native operating system."
    val windows = System.getProperty("os.name").lowercase().contains("windows")
    if (windows) {
        commandLine("pwsh", "-NoProfile", "-File", "scripts/windows-workspace-tool-smoke.ps1")
    } else {
        commandLine("bash", "scripts/verify-stage2-workspace-tools.sh")
    }
}

tasks.register("stage2Check") {
    description = "Runs the complete offline Stage 2 gate plus the current platform native smoke."
    dependsOn(
        "stage2FoundationCheck",
        "verifyModuleBoundaries",
        "verifyPublicNaming",
        "stage2NativeWorkspaceSmoke",
        ":ji-provider-http:test",
        ":ji-provider-openai:test",
        ":ji-provider-anthropic:test",
        ":ji-provider-google:test",
        ":ji-security-api:test",
        ":ji-credential-sqlite:test",
        ":ji-oauth-core:test",
        ":ji-extension-api:test",
        ":ji-workspace-local:test",
        ":ji-resource-local:test",
        ":ji-telemetry-api:test",
        ":ji-telemetry-otel:test",
        ":ji-artifact-api:test",
        ":ji-artifact-filesystem:test",
        ":ji-session-export:test",
        ":ji-cli:test",
    )
}

